void remove_game_ball(void)
{
    --current_ball_count;
    if (game_ball_slot != current_ball_count)
        memcpy(current_ball_pointer, current_ball_pointer + 1, (current_ball_count - game_ball_slot) * sizeof(*current_ball_pointer));
    --game_ball_slot;
}

void spawn_game_ball(int x, int y)
{
    if (current_ball_count < 0x19) {
        current_ball_pointer = game_balls;
        current_ball_pointer += current_ball_count;
        *(int *)(current_ball_pointer + 0) = x << 4;
        current_ball_pointer->y = y << 4;
        current_ball_pointer->velocity_x = 10;
        current_ball_pointer->velocity_y = -20;
        current_ball_pointer->flags &= (unsigned char)~1;
        current_ball_pointer->flags &= (unsigned char)~2;
        current_ball_pointer->behavior = 0;
        ++current_ball_count;
    }
}

